#include <chrono>

int main() {
    constexpr auto ymdl{std::chrono::last / 11 / 2020};
    static_assert(ymdl.day() == std::chrono::day(30) &&
        ymdl.month() == std::chrono::November &&
        ymdl.year() == std::chrono::year(2020) &&
        ymdl.month_day_last() == std::chrono::November / std::chrono::last);
